html:
{#- Presunção de Abandono — reproduces the customer's letter (XSS_RH.FR.031): page 1 the
    letter to RH, page 2 the faltas that originated it. Logo = Empresa Padrão's Company
    logo; code / legal basis / signer / contacts from SIGOS Settings (Documentos Impressos). -#}
{%- set empresa = frappe.db.get_single_value("SIGOS Settings", "empresa_padrao") or frappe.db.get_single_value("Global Defaults", "default_company") -%}
{%- set logo = frappe.db.get_value("Company", empresa, "company_logo") if empresa else None -%}
{%- set codigo = frappe.db.get_single_value("SIGOS Settings", "codigo_formulario_presuncao") or "" -%}
{%- set base_legal = frappe.db.get_single_value("SIGOS Settings", "presuncao_base_legal") or "n.º 3 do artigo 115 da Lei n.º 13/2023, de 25 de agosto" -%}
{%- set assinatura = frappe.db.get_single_value("SIGOS Settings", "presuncao_assinatura") or "Dep. Operativo" -%}
{%- set contactos = (frappe.db.get_single_value("SIGOS Settings", "contactos_documentos") or "").split("\n") | map("trim") | select | list -%}
{%- set local = frappe.db.get_single_value("SIGOS Settings", "local_documentos") or doc.delegacao or "" -%}
{%- set meses = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"] -%}
{%- set d_doc = frappe.utils.getdate(doc.abandono_desde or doc.data_deteccao) if (doc.abandono_desde or doc.data_deteccao) else None -%}
{%- set d_ini = frappe.utils.getdate(doc.primeira_falta) if doc.primeira_falta else None -%}
{%- set posto = frappe.db.get_value("Posto De Vigilancia", doc.posto_de_vigilancia, ["indicativo", "nome_do_posto"], as_dict=True) if doc.posto_de_vigilancia else None -%}
{%- set posto_txt = ((posto.indicativo ~ "-" if posto and posto.indicativo else "") ~ (posto.nome_do_posto if posto and posto.nome_do_posto else (doc.posto_de_vigilancia or ""))) -%}
{%- if doc.criterio == "Nº de Faltas" -%}
	{%- set contagem = (doc.total_faltas or 0) ~ " faltas consecutivas injustificadas" -%}
{%- else -%}
	{%- set contagem = (doc.valor_na_deteccao or doc.total_dias or 0) ~ " dias consecutivos de faltas injustificadas" -%}
{%- endif -%}
{%- set faltas = (doc.faltas or []) | sort(attribute="data", reverse=True) -%}
{%- macro data_extenso(d) -%}{{ "%02d" | format(d.day) }} de {{ meses[d.month - 1] }} de {{ d.year }}{%- endmacro -%}
{%- macro cabeca() -%}
	<div class="pa-logo">{% if logo %}<img src="{{ logo }}">{% endif %}</div>
	{%- if logo %}<div class="pa-wm"><img src="{{ logo }}"></div>{% endif %}
{%- endmacro -%}
{%- macro rodape() -%}
	<div class="pa-foot">
		<table class="pa-codes"><tr>
			<td>{{ (codigo.split("\n")[0] if codigo else "") | e }}</td>
			<td class="r">{{ (codigo.split("\n")[1:] | join(" ") if codigo else "") | e }}</td>
		</tr></table>
		{%- if empresa %}<div class="pa-own">Este documento é propriedade da {{ empresa | upper }}. Não é permitida sua reprodução sem autorização. Depois de impresso este documento é considerado cópia não controlada</div>{% endif %}
		{%- if contactos %}<table class="pa-bar"><tr>{% for c in contactos %}<td>{{ c | e }}</td>{% endfor %}</tr></table>{% endif %}
	</div>
{%- endmacro -%}
<style>
	@page { size: A4 portrait; margin: 10mm 12mm; }
	.pa { font-family: "Times New Roman", Times, serif; color: #111; }
	.pa-page { position: relative; height: 272mm; overflow: hidden; }
	.pa-page2 { page-break-before: always; position: relative; min-height: 272mm; }
	.pa-logo { height: 80px; margin-left: 8px; }
	.pa-logo img { max-height: 80px; max-width: 190px; }
	.pa-wm { position: absolute; top: 70mm; left: 0; right: 0; text-align: center; opacity: .07; z-index: 0; }
	.pa-wm img { width: 150mm; }
	.pa-body { position: relative; z-index: 1; }
	.pa-title { text-align: center; font-size: 18px; margin: 26px 0 70px; }
	.pa-text { font-size: 15px; line-height: 1.75; text-align: justify; margin: 0 6px 22px; }
	.pa-text.gap { margin-top: 36px; }
	.pa-close { text-align: center; font-size: 15px; margin-top: 95px; }
	.pa-sig { width: 280px; margin: 34px auto 0; border-top: 1px solid #111; }
	.pa-sig-l { text-align: center; font-size: 15px; margin-top: 8px; }
	.pa-page .pa-foot { position: absolute; left: 0; right: 0; bottom: 0; }
	.pa-page2 .pa-foot { margin-top: 30px; }
	.pa-codes { width: 100%; font-size: 10px; font-style: italic; margin-bottom: 2px; }
	.pa-codes td.r { text-align: right; }
	.pa-own { text-align: center; font-size: 9.5px; font-style: italic; margin: 0 40px 4px; }
	.pa-bar { width: 100%; background: #1c1c1c; color: #fff; font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; border-collapse: collapse; }
	.pa-bar td { padding: 7px 10px; vertical-align: middle; white-space: nowrap; }
	.pa-list { width: 100%; border-collapse: collapse; font-family: Arial, Helvetica, sans-serif; font-size: 12.5px; margin-top: 10px; position: relative; z-index: 1; }
	.pa-list td { padding: 7px 8px; border-bottom: 1px solid #e3e3e3; }
	.pa-list th { text-align: left; font-size: 10.5px; text-transform: uppercase; color: #555; padding: 4px 8px; border-bottom: 1.5px solid #333; }
	.pa-list .tot td { border-bottom: none; font-weight: bold; padding-top: 10px; }
	.pa-draft { text-align: center; font-size: 11px; color: #888; margin-top: -60px; margin-bottom: 50px; }
</style>
<div class="pa">
	<div class="pa-page">
		{{ cabeca() }}
		<div class="pa-body">
			<div class="pa-title">Presunção De Abandono</div>
			{%- if doc.estado == "Arquivada" %}<div class="pa-draft">ARQUIVADA</div>{% endif %}
			<p class="pa-text">Venho por este meio informar que o vigilante <b>{{ doc.nome_do_vigilante or doc.vigilante }}</b>, com o número <b>{{ doc.mecanografico or "" }}</b>{% if posto_txt %}, afeto ao posto <b>{{ posto_txt }}</b>{% endif %}, não comparece ao seu posto de trabalho desde o dia {{ data_extenso(d_ini) if d_ini else "____" }}, totalizando até à presente data {{ contagem }}.</p>
			<p class="pa-text">Nos termos do {{ base_legal }}, tal situação configura presunção de abandono de posto de trabalho.</p>
			<p class="pa-text gap">Sendo assim, solicitamos os devidos encaminhamentos conforme previsto na legislação laboral vigente.</p>
			<div class="pa-close">{{ local }} aos {{ data_extenso(d_doc) if d_doc else "____" }}</div>
			<div class="pa-sig"></div>
			<div class="pa-sig-l">{{ assinatura }}</div>
		</div>
		{{ rodape() }}
	</div>

	<div class="pa-page2">
		{{ cabeca() }}
		<table class="pa-list">
			<tr><th>Data</th><th>Posto</th><th>Nome</th><th>Número / Regime</th><th>Turno</th></tr>
			{%- for f in faltas %}
			{%- set ind = frappe.db.get_value("Posto De Vigilancia", f.posto, "indicativo") if f.posto else None %}
			<tr>
				<td>{{ frappe.utils.getdate(f.data).strftime("%Y-%m-%d") if f.data else "" }}</td>
				<td>{{ ind or f.posto or "" }}</td>
				<td>{{ doc.nome_do_vigilante or doc.vigilante }}</td>
				<td>{{ doc.mecanografico or "" }} {{ f.regime or "" }}</td>
				<td>{{ f.turno or "" }}</td>
			</tr>
			{%- endfor %}
			<tr class="tot"><td colspan="3">{{ faltas | length }} turno(s) em falta</td><td colspan="2">{{ doc.total_faltas or 0 }} falta(s)</td></tr>
		</table>
		{{ rodape() }}
	</div>
</div>
